:SequentialStepMission a owl:Class ; rdfs:subClassOf :ArcaneMission ;
    rdfs:label "顺序任务环节"@zh ;
    rdfs:comment "在探知、协调、具现主线上按配置建立顺序环节，同一角色可重复出现；每个环节分配一个执行实例，不强制评估，不声明联合效果公式。"@zh .
:hasSequentialStep a owl:ObjectProperty ;
    rdfs:label "包含顺序任务环节"@zh ; rdfs:domain :ArcaneMission ; rdfs:range :SequentialStepMission .
:stepActivity a owl:DatatypeProperty ;
    rdfs:label "环节活动"@zh ; rdfs:domain :SequentialStepMission ; rdfs:range xsd:string .
:stepIndex a owl:DatatypeProperty ;
    rdfs:label "模板内环节次序"@zh ; rdfs:domain :SequentialStepMission ; rdfs:range xsd:integer .
:stepTarget a owl:ObjectProperty ;
    rdfs:label "顺序环节目标"@zh ; rdfs:domain :SequentialStepMission ; rdfs:range :Target ;
    rdfs:comment "独立于整体任务hasTarget，避免把整体任务的全部角色能力要求施加到每一个环节。"@zh .

